package com.citacloud.app.models;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="alergias_paciente") public class AlergiaPaciente { @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; @Column(name="paciente_id",nullable=false) private UUID pacienteId; @Column(nullable=false) private String alergeno; private String tipo; @Column(columnDefinition="TEXT") private String reaccion; @Column(nullable=false) private String severidad="LEVE"; private String estado="ACTIVA"; @Column(name="fecha_aproximada") private LocalDate fechaAproximada; @Column(columnDefinition="TEXT") private String observaciones; @Column(name="registrado_por") private UUID registradoPor; @Column(name="creado_en") private LocalDateTime creadoEn; @Column(name="actualizado_en") private LocalDateTime actualizadoEn; public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public String getAlergeno(){return alergeno;} public String getTipo(){return tipo;} public String getReaccion(){return reaccion;} public String getSeveridad(){return severidad;} public String getEstado(){return estado;} public LocalDate getFechaAproximada(){return fechaAproximada;} public String getObservaciones(){return observaciones;} public UUID getRegistradoPor(){return registradoPor;} public LocalDateTime getCreadoEn(){return creadoEn;} public LocalDateTime getActualizadoEn(){return actualizadoEn;} public void setEmpresaId(UUID v){empresaId=v;} public void setPacienteId(UUID v){pacienteId=v;} public void setAlergeno(String v){alergeno=v;} public void setTipo(String v){tipo=v;} public void setReaccion(String v){reaccion=v;} public void setSeveridad(String v){severidad=v;} public void setEstado(String v){estado=v;} public void setFechaAproximada(LocalDate v){fechaAproximada=v;} public void setObservaciones(String v){observaciones=v;} public void setRegistradoPor(UUID v){registradoPor=v;} public void setCreadoEn(LocalDateTime v){creadoEn=v;} public void setActualizadoEn(LocalDateTime v){actualizadoEn=v;} }
